# 1.11 00:21 (the owner): the villas of C3 and D3 — every villa on its own lot, with a border and its own way in from a real road
def _cut(r, c, rad, n=60):
    """a rect minus a disc (the turning circle): the polygon of a lot whose front is the circle — the rect's border, and where it
    enters the disc, the arc of the circle that lies inside the rect"""
    x0, y0, x1, y1 = r; cx, cy = c
    edge = [(x0, y0), (x1, y0), (x1, y1), (x0, y1)]; P_ = []
    for k in range(4):
        (ax, ay), (bx, by) = edge[k], edge[(k + 1) % 4]
        for i in range(n): t = i / n; P_.append((ax + (bx - ax) * t, ay + (by - ay) * t))
    inn = [math.hypot(x - cx, y - cy) < rad for x, y in P_]
    if not any(inn): return [(round(x, 1), round(y, 1)) for x, y in edge]
    k0 = next(k for k in range(len(P_)) if not inn[k]); P_ = P_[k0:] + P_[:k0]; inn = inn[k0:] + inn[:k0]
    out = []; k = 0
    def ins(x, y): return x0 + 1 < x < x1 - 1 and y0 + 1 < y < y1 - 1
    while k < len(P_):
        if not inn[k]: out.append(P_[k]); k += 1; continue
        a0 = math.atan2(P_[k][1] - cy, P_[k][0] - cx); m = k
        while m < len(P_) and inn[m]: m += 1
        a1 = math.atan2(P_[m - 1][1] - cy, P_[m - 1][0] - cx)
        d = (a1 - a0) % (2 * math.pi); mid = a0 + d / 2
        if not ins(cx + rad * math.cos(mid), cy + rad * math.sin(mid)): d -= 2 * math.pi
        for q in range(25): a = a0 + d * q / 24; out.append((cx + rad * math.cos(a), cy + rad * math.sin(a)))
        k = m
    res = []
    for x, y in out:
        if not res or math.hypot(x - res[-1][0], y - res[-1][1]) > 3: res.append((round(x, 1), round(y, 1)))
    return res
def villa(zone, id, r, label, why, front, poly_c=None, use='home', house=True):
    kw = dict(use=use)
    if poly_c: kw['poly'] = _cut(r, poly_c, 129)
    it(zone, id, 'lot', r, label, why, **kw)
    if house:   # the house: 15 × 10.8 m (uses: villa 150 × 108 px), 5 m behind the front of the lot
        x0, y0, x1, y1 = r; cy_ = (y0 + y1) / 2
        hx = (x1 - 50 - 150, x1 - 50) if front == 'E' else (x0 + 50, x0 + 50 + 150)
        if poly_c and front == 'E': hx = (x0 + 5, x0 + 155)
        if poly_c and front == 'W': hx = (x1 - 155, x1 - 5)
        S.append(dict(zone=zone, id=id + '-H', kind='house', rect=(hx[0], cy_ - 54, hx[1], cy_ + 54), label='הבית', why='הטביעה של הווילה (150 × 108 px)', parent=id))
